def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of str, each token is an integer or '+', '-', '*', '/'.
    Division truncates toward zero as in int(a/b) in Python 3.
    """
    stack = []
    for t in tokens:
        if t in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if t == "+":
                res = a + b
            elif t == "-":
                res = a - b
            elif t == "*":
                res = a * b
            else:  # division
                # truncates toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

