def solve(s):
    """Balanced brackets check, robust to non-string input.
    Returns True if brackets are balanced; non-string inputs are treated as having no brackets.
    """
    if not isinstance(s, str):
        return True
    pairs = {')':'(', ']':'[', '}':'{'}
    opens = set(pairs.values())
    stack = []
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

