def solve(s):
    """Balanced brackets check for batch 2, robust to non-string inputs.
    Returns True if brackets are balanced; non-string inputs are treated as having no brackets.
    """
    if not isinstance(s, str):
        return True
    pairs = {')':'(', ']':'[', '}':'{'}
    opening = set(pairs.values())
    stack = []
    for ch in s:
